import { useEffect } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { View } from '@react-three/drei';
import { useHasActiveRuntimeModels } from './model-activity';
import { useModelRenderPixelRatio } from '../../rendering/model-render-resolution';

const RUNTIME_MODEL_FPS = 30;

export default function RuntimeModel3DStage() {
  const animate = useHasActiveRuntimeModels();
  const pixelRatio = useModelRenderPixelRatio();
  return (
    <div
      className="amp-runtime-model-stage"
      data-amp-model-pixel-ratio={pixelRatio}
      data-amp-model-stage-animate={String(animate)}
      aria-hidden
    >
      <Canvas
        frameloop="demand"
        dpr={pixelRatio}
        gl={{ alpha: true, antialias: false, powerPreference: 'high-performance', preserveDrawingBuffer: false, stencil: false }}
        fallback={null}
        onCreated={({ gl }) => gl.setClearColor(0x000000, 0)}
      >
        <ContextRecovery />
        <FrameClear />
        <RenderInvalidator animate={animate} />
        <View.Port />
      </Canvas>
    </div>
  );
}

function FrameClear() {
  useFrame(({ gl }) => {
    gl.setScissorTest(false);
    gl.setClearColor(0x000000, 0);
    gl.clear(true, true, true);
  }, -100_000);
  return null;
}

function ContextRecovery() {
  const gl = useThree((state) => state.gl);
  const invalidate = useThree((state) => state.invalidate);
  useEffect(() => {
    const canvas = gl.domElement;
    const lost = (event: Event) => event.preventDefault();
    const restored = () => invalidate();
    canvas.addEventListener('webglcontextlost', lost);
    canvas.addEventListener('webglcontextrestored', restored);
    return () => {
      canvas.removeEventListener('webglcontextlost', lost);
      canvas.removeEventListener('webglcontextrestored', restored);
    };
  }, [gl, invalidate]);
  return null;
}

function RenderInvalidator({ animate }: { animate: boolean }) {
  const invalidate = useThree((state) => state.invalidate);
  useEffect(() => {
    invalidate();
    if (!animate) return;
    let frame = 0;
    let last = 0;
    const interval = 1000 / RUNTIME_MODEL_FPS;
    const tick = (time: number) => {
      if (time - last >= interval) {
        last = time;
        invalidate();
      }
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [animate, invalidate]);
  return null;
}
